edits.newText:
// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks. Brick resolution is delegated to the
// pure `brickHit()`; the previous position is recorded so the sweep can catch
// a fast ball that would otherwise jump over a brick (tunnelling, #1).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Where the ball came from, for the swept brick collision below.
  ball.prevX = ball.x;
  ball.prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

