// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit — that's brickHit's job (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick collision & bounce (issue #1) -----------------------------------

// How deep the ball sits inside each of the brick's four faces. Each value is
// the penetration of the ball's edge past the opposite face of the brick.
function penetration(ball, brick) {
  return {
    left: ball.x + ball.r - brick.x, // ball right edge past the brick left edge
    right: brick.x + brick.w - (ball.x - ball.r), // ball left edge past the brick right edge
    top: ball.y + ball.r - brick.y, // ball bottom edge past the brick top edge
    bottom: brick.y + brick.h - (ball.y - ball.r), // ball top edge past the brick bottom edge
  };
}

// The t-interval over which `prev + delta * t` (t in [0, 1]) stays inside
// [lo, hi], or null when it never does. Used to sweep the ball's path.
function axisInterval(prev, delta, lo, hi) {
  if (delta === 0) {
    return prev >= lo && prev <= hi ? [0, 1] : null;
  }
  let a = (lo - prev) / delta;
  let b = (hi - prev) / delta;
  if (a > b) [a, b] = [b, a];
  return [a, b];
}

// Sweeps the ball (as its bounding box, like collides) along the segment from
// (prevX, prevY) to its current position and returns the earliest moment it
// overlaps `brick`, or null. The `axis` is the one whose range the ball
// entered last — that's the face it hit. A hit is only real if the ball
// strictly penetrates somewhere inside the overlap interval: a path that
// merely grazes the brick's edge (zero-width overlap, e.g. sliding along a
// face) must not bounce.
function sweptHit(ball, brick, prevX, prevY) {
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;
  const ix = axisInterval(prevX, dx, brick.x - ball.r, brick.x + brick.w + ball.r);
  const iy = axisInterval(prevY, dy, brick.y - ball.r, brick.y + brick.h + ball.r);
  if (!ix || !iy) return null;
  const tIn = Math.max(ix[0], iy[0]);
  const tOut = Math.min(ix[1], iy[1]);
  if (tIn >= tOut || tOut < 0 || tIn > 1) return null;

  // Confirm a strict overlap at the middle of the overlap interval: this
  // rejects degenerate contacts that stay glued to a face or a corner.
  const mid = (tIn + tOut) / 2;
  const x = prevX + dx * mid;
  const y = prevY + dy * mid;
  if (!collides({ x, y, r: ball.r }, brick)) return null;

  const axis = Math.abs(ix[0] - iy[0]) < EPS ? 'both' : ix[0] > iy[0] ? 'x' : 'y';
  return { t: Math.max(0, tIn), axis };
}

// Bounces a ball that is already inside one or more bricks. The face hit is
// the one with the smallest penetration; a tie (diagonal arrival) bounces both
// axes. The ball is pushed back out along the bounce axis beyond EVERY brick
// it overlaps: the 8 px grid gap is narrower than the 14 px ball, so a seam
// overlaps two bricks in the same pass and the bounce must apply exactly once.
function resolveOverlap(ball, bricks) {
  let chosen = null;
  let best = Infinity;
  for (const brick of bricks) {
    const p = penetration(ball, brick);
    const penX = Math.min(p.left, p.right);
    const penY = Math.min(p.top, p.bottom);
    const min = Math.min(penX, penY);
    if (min < best) {
      best = min;
      chosen = { brick, p, penX, penY };
    }
  }
  const { p, penX, penY } = chosen;

  if (penX < penY) {
    ball.vx = -ball.vx;
    ball.x = p.left < p.right
      ? Math.min(...bricks.map((b) => b.x)) - ball.r
      : Math.max(...bricks.map((b) => b.x + b.w)) + ball.r;
  } else if (penY < penX) {
    ball.vy = -ball.vy;
    ball.y = p.top < p.bottom
      ? Math.min(...bricks.map((b) => b.y)) - ball.r
      : Math.max(...bricks.map((b) => b.y + b.h)) + ball.r;
  } else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = p.left <= p.right
      ? Math.min(...bricks.map((b) => b.x)) - ball.r
      : Math.max(...bricks.map((b) => b.x + b.w)) + ball.r;
    ball.y = p.top <= p.bottom
      ? Math.min(...bricks.map((b) => b.y)) - ball.r
      : Math.max(...bricks.map((b) => b.y + b.h)) + ball.r;
  }
}

// Bounces a fast ball that crossed bricks between two sampled positions.
// `hits` is sorted by entry time: the earliest brick gives the face actually
// hit, the others were plowed through in the same pass. Push-out clears every
// brick of the pass so the next frame cannot re-flip.
function resolveSweep(ball, hits) {
  const first = hits[0];
  const xs = hits.map((h) => h.brick.x);
  const xe = hits.map((h) => h.brick.x + h.brick.w);
  const ys = hits.map((h) => h.brick.y);
  const ye = hits.map((h) => h.brick.y + h.brick.h);

  if (first.axis === 'x') {
    ball.vx = -ball.vx;
    ball.x = ball.vx > 0 ? Math.max(...xe) + ball.r : Math.min(...xs) - ball.r;
  } else if (first.axis === 'y') {
    ball.vy = -ball.vy;
    ball.y = ball.vy > 0 ? Math.max(...ye) + ball.r : Math.min(...ys) - ball.r;
  } else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = ball.vx > 0 ? Math.max(...xe) + ball.r : Math.min(...xs) - ball.r;
    ball.y = ball.vy > 0 ? Math.max(...ye) + ball.r : Math.min(...ys) - ball.r;
  }
}

// Pure brick collision. Destroys every brick the ball touched during the step
// that took it from (prevX, prevY) to its current position and bounces the
// ball exactly once, either against the face it currently overlaps (smallest
// penetration wins, both axes on a diagonal corner) or against the face it
// crossed on the way (tunnelling sweep). `prevX`/`prevY` are read from the
// ball when present (step() records them); without them the sweep collapses to
// the current position.
//
// Returns the destroyed bricks.
export function brickHit(ball, bricks) {
  const prevX = Number.isFinite(ball.prevX) ? ball.prevX : ball.x;
  const prevY = Number.isFinite(ball.prevY) ? ball.prevY : ball.y;

  // The ball is already inside a brick: classic per-face bounce.
  const overlapping = bricks.filter((b) => b.alive && collides(ball, b));
  if (overlapping.length > 0) {
    for (const brick of overlapping) brick.alive = false;
    resolveOverlap(ball, overlapping);
    return overlapping;
  }

  // The ball jumped over a brick between the two samples: sweep the segment.
  const swept = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweptHit(ball, brick, prevX, prevY);
    if (hit) swept.push({ brick, ...hit });
  }
  if (swept.length === 0) return [];
  swept.sort((a, b) => a.t - b.t);
  for (const s of swept) s.brick.alive = false;
  resolveSweep(ball, swept);
  return swept.map((s) => s.brick);
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
